      interpretation = "\u0421\u0442\u0440\u0435\u0441\u0441\u0430 \u0431\u043E\u043B\u044C\u0448\u0435, \u0447\u0435\u043C \u043E\u0431\u044B\u0447\u043D\u043E. \u0416\u0438\u0437\u043D\u044C \u043A\u0430\u0436\u0435\u0442\u0441\u044F \u0441\u043B\u043E\u0436\u043D\u043E\u0439, \u043D\u043E \u0432 \u0446\u0435\u043B\u043E\u043C \u0432\u044B \u0441\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442\u0435\u0441\u044C.";
      recommendation = "\u041F\u0435\u0440\u0435\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0440\u0435\u0436\u0438\u043C \u0441\u043D\u0430, \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0443 \u0438 \u0431\u0430\u043B\u0430\u043D\u0441. \u0415\u0441\u043B\u0438 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0434\u043B\u0438\u0442\u0441\u044F \u043C\u0435\u0441\u044F\u0446 \u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u2014 \u043E\u0431\u0441\u0443\u0434\u0438\u0442\u0435 \u0441 \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u043E\u043C.";
