      interpretation = "\u0412\u0430\u0448\u0438 \u043A\u043E\u0433\u043D\u0438\u0442\u0438\u0432\u043D\u044B\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u0432 \u0446\u0435\u043B\u043E\u043C \u0433\u0438\u0431\u043A\u0438\u0435. \u042D\u0442\u043E \u0441\u043D\u0438\u0436\u0430\u0435\u0442 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u044C \u043A \u0434\u0435\u043F\u0440\u0435\u0441\u0441\u0438\u0438 \u0438 \u0442\u0440\u0435\u0432\u043E\u0433\u0435.";
      recommendation = "\u041F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u043D\u0430\u0432\u044B\u043A\u0438 \u0440\u0435\u0444\u043B\u0435\u043A\u0441\u0438\u0438 \u0438 \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0433\u0438\u0431\u043A\u043E\u0441\u0442\u0438.";
