      interpretation = "\u0416\u0451\u0441\u0442\u043A\u0438\u0435 \u0443\u0441\u043B\u043E\u0432\u043D\u044B\u0435 \u0443\u0431\u0435\u0436\u0434\u0435\u043D\u0438\u044F \u0432\u044B\u0440\u0430\u0436\u0435\u043D\u044B. \u041F\u043E \u043C\u043E\u0434\u0435\u043B\u0438 \u0411\u0435\u043A\u0430, \u044D\u0442\u043E \u0437\u043D\u0430\u0447\u0438\u043C\u044B\u0439 \u0444\u0430\u043A\u0442\u043E\u0440 \u0443\u044F\u0437\u0432\u0438\u043C\u043E\u0441\u0442\u0438 \u043A \u0434\u0435\u043F\u0440\u0435\u0441\u0441\u0438\u0432\u043D\u044B\u043C \u044D\u043F\u0438\u0437\u043E\u0434\u0430\u043C.";
      recommendation = "\u0421\u0442\u043E\u0438\u0442 \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u044C\u0441\u044F \u043A \u041A\u041F\u0422-\u0442\u0435\u0440\u0430\u043F\u0435\u0432\u0442\u0443. \u0420\u0430\u0431\u043E\u0442\u0430 \u0441 \u0443\u0431\u0435\u0436\u0434\u0435\u043D\u0438\u044F\u043C\u0438 \u2014 \u043E\u0441\u043D\u043E\u0432\u0430 \u0434\u043E\u043B\u0433\u043E\u0441\u0440\u043E\u0447\u043D\u043E\u0439 \u0443\u0441\u0442\u043E\u0439\u0447\u0438\u0432\u043E\u0441\u0442\u0438 \u043A \u0434\u0435\u043F\u0440\u0435\u0441\u0441\u0438\u0438.";
