    // 11 reflection
    "\u0417\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E \u0441\u0432\u043E\u0438 \u0447\u0443\u0432\u0441\u0442\u0432\u0430 \u0438 \u0430\u043D\u0430\u043B\u0438\u0437\u0438\u0440\u0443\u044E \u0438\u0445",
    // 12 reflection
    "\u0414\u0443\u043C\u0430\u044E \u043E \u043D\u0435\u0434\u0430\u0432\u043D\u0435\u0439 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438, \u0436\u0435\u043B\u0430\u044F, \u0447\u0442\u043E\u0431\u044B \u043E\u043D\u0430 \u043F\u0440\u043E\u0448\u043B\u0430 \u043B\u0443\u0447\u0448\u0435",
    // 13 brooding
    "\u0414\u0443\u043C\u0430\u044E: \xAB\u042F \u043D\u0435 \u0441\u043C\u043E\u0433\u0443 \u0441\u043E\u0441\u0440\u0435\u0434\u043E\u0442\u043E\u0447\u0438\u0442\u044C\u0441\u044F, \u0435\u0441\u043B\u0438 \u0431\u0443\u0434\u0443 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0442\u044C \u0442\u0430\u043A \u0441\u0435\u0431\u044F \u0447\u0443\u0432\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C\xBB",
    // 14
    "\u0414\u0443\u043C\u0430\u044E: \xAB\u041F\u043E\u0447\u0435\u043C\u0443 \u0443 \u043C\u0435\u043D\u044F \u0435\u0441\u0442\u044C \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u043D\u0435\u0442 \u0443 \u0434\u0440\u0443\u0433\u0438\u0445?\xBB",
    // 15 brooding
    "\u0414\u0443\u043C\u0430\u044E: \xAB\u041F\u043E\u0447\u0435\u043C\u0443 \u044F \u043D\u0435 \u043C\u043E\u0433\u0443 \u0441\u043F\u0440\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u0441 \u044D\u0442\u0438\u043C \u043B\u0443\u0447\u0448\u0435?\xBB",
    // 16 brooding
    "\u0414\u0443\u043C\u0430\u044E \u043E \u0442\u043E\u043C, \u043A\u0430\u043A\u043E\u0439 \u044F \u0433\u0440\u0443\u0441\u0442\u043D\u044B\u0439",
    // 17
    "\u0414\u0443\u043C\u0430\u044E \u043E \u0432\u0441\u0435\u0445 \u0441\u0432\u043E\u0438\u0445 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043A\u0430\u0445, \u043F\u0440\u043E\u0432\u0430\u043B\u0430\u0445, \u043E\u0448\u0438\u0431\u043A\u0430\u0445",
    // 18
    "\u0414\u0443\u043C\u0430\u044E \u043E \u0442\u043E\u043C, \u0447\u0442\u043E \u0443 \u043C\u0435\u043D\u044F \u043D\u0435\u0442 \u0436\u0435\u043B\u0430\u043D\u0438\u044F \u0447\u0442\u043E-\u043B\u0438\u0431\u043E \u0434\u0435\u043B\u0430\u0442\u044C",
    // 19
