      interpretation = "\u0412\u0430\u043C \u0432 \u0446\u0435\u043B\u043E\u043C \u043D\u0435 \u0441\u0432\u043E\u0439\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u043F\u043E\u0434\u043E\u043B\u0433\u0443 \u043F\u0440\u043E\u043A\u0440\u0443\u0447\u0438\u0432\u0430\u0442\u044C \u0432 \u0433\u043E\u043B\u043E\u0432\u0435 \u043D\u0435\u043F\u0440\u0438\u044F\u0442\u043D\u044B\u0435 \u043C\u044B\u0441\u043B\u0438 \u043E \u0441\u0435\u0431\u0435 \u0438 \u0441\u0432\u043E\u0451\u043C \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0438.";
      recommendation = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0439\u0442\u0435 \u043D\u0430\u0432\u044B\u043A\u0438 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u044F \u0438 \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0433\u043E \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u043F\u0440\u043E\u0431\u043B\u0435\u043C \u2014 \u044D\u0442\u043E \u043B\u0443\u0447\u0448\u0430\u044F \u0437\u0430\u0449\u0438\u0442\u0430 \u043E\u0442 \u0440\u0443\u043C\u0438\u043D\u0430\u0446\u0438\u0438.";
