    { when: "14\u201319 \u0431\u0430\u043B\u043B\u043E\u0432", action: "\u041B\u0451\u0433\u043A\u0430\u044F \u0441\u0442\u0435\u043F\u0435\u043D\u044C. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0447\u0435\u0441\u043A\u0443\u044E \u0430\u043A\u0442\u0438\u0432\u0430\u0446\u0438\u044E \u0438 \u043F\u043E\u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0439\u0442\u0435 2 \u043D\u0435\u0434\u0435\u043B\u0438." },
    { when: "20\u201328 \u0431\u0430\u043B\u043B\u043E\u0432", action: "\u0423\u043C\u0435\u0440\u0435\u043D\u043D\u0430\u044F. \u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435\u0441\u044C \u043A \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0443 \u0438\u043B\u0438 \u043F\u0441\u0438\u0445\u043E\u0442\u0435\u0440\u0430\u043F\u0435\u0432\u0442\u0443, \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0449\u0435\u043C\u0443 \u0432 \u041A\u041F\u0422." },
    { when: "\u2265 29 \u0431\u0430\u043B\u043B\u043E\u0432", action: "\u0422\u044F\u0436\u0451\u043B\u0430\u044F. \u041E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u043A \u043F\u0441\u0438\u0445\u0438\u0430\u0442\u0440\u0443 \u0438 \u043F\u0441\u0438\u0445\u043E\u0442\u0435\u0440\u0430\u043F\u0435\u0432\u0442\u0443 \u2014 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u0442\u0435\u0440\u0430\u043F\u0438\u0438 \u0438 \u043C\u0435\u0434\u0438\u043A\u0430\u043C\u0435\u043D\u0442\u043E\u0432." }
