// src/lib/mcp/tools/list-tests.ts
var list_tests_default = defineTool3({
  name: "list_psychological_tests",
  title: "List psychological tests",
  description: "List validated self-report psychological tests available on CognitionX (PHQ-9, GAD-7, BAT, PSS-10, etc.). Returns slug, code, title, cluster, and duration. Filter by cluster (e.g. 'depression', 'anxiety', 'burnout').",
  inputSchema: {
    cluster: z3.string().optional().describe(
      "Optional cluster filter: depression, anxiety, burnout, stress, self-esteem, it, cbt-tools, trauma, sleep, addiction, relationships, personality, eating."
    )
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ cluster }) => {
    const items = tests.filter((t) => !cluster || t.cluster === cluster).map((t) => ({
      slug: t.slug,
      code: t.code,
      title: t.title,
      cluster: t.cluster,
      clusterLabel: t.clusterLabel,
      durationMin: t.durationMin,
      audience: t.audience,
      url: `https://cognitionx.cloud/tools/tests/${t.slug}`
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { tests: items, total: items.length }
    };
  }
});

// src/lib/mcp/tools/search-blog.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z4 } from "npm:zod@^3.25.76";
var search_blog_default = defineTool4({
  name: "search_blog",
  title: "Search blog",
  description: "Full-text search across CognitionX blog posts (title, description, tags, body). Case-insensitive substring match. Returns matching posts with slug, title, and a short snippet.",
  inputSchema: {
    query: z4.string().min(1).describe("Search query (Russian or English)."),
    limit: z4.number().int().min(1).max(50).optional().describe("Max results (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, limit }) => {
    const q = query.toLowerCase();
    const results = blogPosts.map((p) => {
      const body = p.content.map((b) => b.text).join(" ").replace(/<[^>]+>/g, " ");
      const haystack = `${p.title}
${p.description}
${p.tags.join(" ")}
${body}`.toLowerCase();
      const idx = haystack.indexOf(q);
      if (idx === -1) return null;
      const snippet = haystack.slice(Math.max(0, idx - 80), idx + 200).replace(/\s+/g, " ").trim();
      return {
        slug: p.slug,
        title: p.title,
        description: p.description,
        tags: p.tags,
        url: `https://cognitionx.cloud/blog/${p.slug}`,
        snippet: `\u2026${snippet}\u2026`
      };
    }).filter((x) => x !== null).slice(0, limit ?? 10);
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      structuredContent: { results, total: results.length }
    };
  }
});

// src/lib/mcp/index.ts
var mcp_default = defineMcp({
  name: "cognitionx-mcp",
  title: "CognitionX MCP",
  version: "0.1.0",
  instructions: "Read-only tools for CognitionX (Russian CBT and schema-therapy resource by psychologist Dmitry Yatsko). Use `list_blog_posts` and `search_blog` to discover articles, `get_blog_post` to read the full body, and `list_psychological_tests` to enumerate validated self-report tests (PHQ-9, GAD-7, BAT, etc.). All content is public.",
  tools: [list_blog_posts_default, get_blog_post_default, list_tests_default, search_blog_default]
});

